input.newString:
function draw() {
  // Space gradient background
  const grad = ctx.createLinearGradient(0, 0, 0, canvas.height);
  grad.addColorStop(0, '#001');
  grad.addColorStop(1, '#000');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Starfield (twinkling)
  ctx.fillStyle = '#fff';
  stars.forEach(s => {
    ctx.beginPath();
    ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
    ctx.fill();
  });

  // Ship with thrust flame
  ctx.save();
  ctx.translate(ship.x, ship.y);
  ctx.rotate(ship.angle);
  // Ship body
  ctx.fillStyle = '#0f0';
  ctx.beginPath();
  ctx.moveTo(12, 0);
  ctx.lineTo(-8, -6);
  ctx.lineTo(-8, 6);
  ctx.closePath();
  ctx.fill();
  // Thrust flame
  if (ship.thrusting) {
    ctx.fillStyle = 'orange';
    ctx.beginPath();
    ctx.moveTo(-8, -4);
    ctx.lineTo(-14, 0);
    ctx.lineTo(-8, 4);
    ctx.closePath();
    ctx.fill();
  }
  ctx.restore();

  // Asteroids with simple shading
  asteroids.forEach(a => {
    const gradA = ctx.createRadialGradient(a.x, a.y, a.r * 0.2, a.x, a.y, a.r);
    gradA.addColorStop(0, '#aaa');
    gradA.addColorStop(1, '#555');
    ctx.fillStyle = gradA;
    ctx.beginPath();
    ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2);
    ctx.fill();
  });

  // Orbs with glow effect
  orbs.forEach(o => {
    const orbGrad = ctx.createRadialGradient(o.x, o.y, 0, o.x, o.y, o.r * 2);
    orbGrad.addColorStop(0, '#ff0');
    orbGrad.addColorStop(1, 'rgba(255,165,0,0)');
    ctx.fillStyle = orbGrad;
    ctx.beginPath();
    ctx.arc(o.x, o.y, o.r, 0, Math.PI * 2);
    ctx.fill();
  });

  // UI overlay
  ctx.fillStyle = '#fff';
  ctx.font = '16px sans-serif';
  ctx.fillText('Score: ' + score, 10, 20);
  if (gameOver) {
    ctx.fillStyle = 'rgba(0,0,0,0.7)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#f44';
    ctx.font = '48px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
  }
}

